import{_ as t,o as r,c as a,ah as n}from"./chunks/framework.C-FRNfAJ.js";const m=JSON.parse('{"title":"Bienvenue","description":"","frontmatter":{"layout":"doc"},"headers":[],"relativePath":"guide/bienvenue.md","filePath":"src/guide/bienvenue.md"}'),s={name:"guide/bienvenue.md"};function i(o,e,u,d,l,c){return r(),a("div",null,[...e[0]||(e[0]=[n('<h1 id="bienvenue" tabindex="-1">Bienvenue <a class="header-anchor" href="#bienvenue" aria-label="Permalink to &quot;Bienvenue&quot;">​</a></h1><p>Kura est la plateforme administrative et financière de NextBoxx, l&#39;organisme de formation d&#39;edPage group. Elle accompagne une personne de sa candidature jusqu&#39;à son certificat, et suit au passage tout ce qui relève de l&#39;administration : dossier, convention, paiements, présence, résultats.</p><h2 id="kura-et-seve" tabindex="-1">Kura et Sève <a class="header-anchor" href="#kura-et-seve" aria-label="Permalink to &quot;Kura et Sève&quot;">​</a></h2><p>Deux outils se partagent le parcours :</p><table tabindex="0"><thead><tr><th></th><th>Kura</th><th>Sève</th></tr></thead><tbody><tr><td>Rôle</td><td>Dossier, conventions, factures, certificats</td><td>Cours, classes virtuelles, notes, messagerie</td></tr><tr><td>On y fait</td><td>Candidater, signer, payer, télécharger ses documents</td><td>Suivre sa formation</td></tr><tr><td>Connexion</td><td>Compte NextBoxx (e-mail et mot de passe)</td><td>Avec le même compte NextBoxx : Sève s&#39;appuie sur Kura pour vous identifier, sans second mot de passe</td></tr></tbody></table><p>Votre compte Sève s&#39;ouvre à votre place, une fois la première tranche de la formation payée. Kura transmet ensuite à Sève ce qui concerne votre accès : ouverture, suspension en cas d&#39;impayé, passage à l&#39;état Canopé après le certificat. En sens inverse, Sève remonte vers Kura vos présences aux classes virtuelles et vos notes.</p><h2 id="un-compte-plusieurs-roles" tabindex="-1">Un compte, plusieurs rôles <a class="header-anchor" href="#un-compte-plusieurs-roles" aria-label="Permalink to &quot;Un compte, plusieurs rôles&quot;">​</a></h2><p>Une personne n&#39;a qu&#39;un seul compte NextBoxx, identifié par son adresse e-mail. Ce compte cumule les rôles au fil du temps : candidat, puis apprenant, puis Canopé, et pourquoi pas formateur ou financeur d&#39;événement plus tard. On ne recrée jamais de compte.</p><p>Ce que vous voyez dans le menu dépend de vos rôles. Il est rangé en six rubriques :</p><table tabindex="0"><thead><tr><th>Rubrique</th><th>Contenu</th></tr></thead><tbody><tr><td>Pilotage</td><td>Tableau de bord, vue Direction, reporting</td></tr><tr><td>Formation</td><td>Catalogue, cohortes, rentabilité, communication</td></tr><tr><td>Parcours</td><td>Candidatures, Inscriptions, Demandes entreprises, Apprenants financés, Ma candidature, Mon inscription, Mes demandes entreprise, Mes documents</td></tr><tr><td>Activités</td><td>Événements, L&#39;Éclosion, Partenariats technologiques, Comité d&#39;investissement, Mes événements, Mes financements, Mon projet L&#39;Éclosion</td></tr><tr><td>Finance</td><td>Facturation, Commissions, Rémunérations, Partenaires marketing, Mes commissions, Ma rémunération, Mes factures</td></tr><tr><td>Administration</td><td>Demandes de rôle, Utilisateurs, Comptes organisation, Jours fériés, Synchronisation Sève, Journal d&#39;audit, Réglages</td></tr></tbody></table><p>Une entrée absente de votre menu ne vous est pas ouverte : demandez le rôle correspondant (voir <a href="./premiers-pas.html#demander-un-role">Premiers pas</a>).</p><h2 id="comment-lire-ce-guide" tabindex="-1">Comment lire ce guide <a class="header-anchor" href="#comment-lire-ce-guide" aria-label="Permalink to &quot;Comment lire ce guide&quot;">​</a></h2><p>Chaque rôle a sa section, dans le menu de gauche. Commencez par <a href="./premiers-pas.html">Premiers pas</a>, commun à tous, puis allez à votre parcours.</p><ul><li><strong>Vous postulez à une formation, ou vous suivez déjà la vôtre</strong> : <a href="./apprenant/candidature.html">Parcours de l&#39;apprenant</a>.</li><li><strong>Vous représentez une entreprise</strong> (financer un apprenant, former vos équipes, recruter) : <a href="./entreprises/financeur.html">Entreprises et financeurs</a>.</li><li><strong>Vous enseignez, accompagnez ou instruisez les candidatures</strong> : <a href="./equipe/formateur.html">L&#39;équipe pédagogique</a>.</li><li><strong>Vous coordonnez la formation</strong> (catalogue, cohortes, facturation, certification) : <a href="./coordinateur/catalogue.html">Coordinateur pédagogique</a>.</li><li><strong>Vous participez à un événement, financez, incubez ou nouez un partenariat</strong> : <a href="./activites/evenements.html">Activités élargies</a>.</li><li><strong>Vous pilotez ou administrez la plateforme</strong> : <a href="./direction/pilotage.html">Direction et reporting</a> et <a href="./administrateur/comptes-et-roles.html">Administrateur</a>.</li></ul>',14)])])}const h=t(s,[["render",i]]);export{m as __pageData,h as default};
